1	package main
2	
3	import (
4		"errors"
5		"flag"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10		"time"
11	)
12	
13	const appName = "caretrack"
14	
15	const helpText = `caretrack — 本地设备资产登记与维修工单闭环工具
16	
17	数据保存在本地目录，无外部服务依赖，仅支持单进程顺序调用。
18	
19	用法:
20	  caretrack <命令> [参数]
21	
22	命令:
23	  register   登记资产（企业资产编号、名称、位置）
24	  list       列出全部资产及当前状态
25	  detail     查看资产详情及其未关闭工单编号、保养计划
26	  report     对资产报修，创建工单，资产转为“维修中”
27	  assign     为未关闭工单派工或转派维修人员
28	  ticket     按工单编号查询工单状态与负责人
29	  close      关闭工单并填写维修结果，设备恢复“可用”
30	  cancel     取消误报或不再需要维修的未关闭工单，设备恢复“可用”
31	  plan       为资产建立唯一的周期保养计划（不可覆盖）
32	  maintain   登记当前周期的保养完成，推进下一到期日
33	  due        按指定日期列出到期的保养计划（只读）
34	  history    按资产查看履历（报修、派工、关闭、取消、保养建立与完成事件）
35	  downtime   查询时间窗口内的设备维修停机时长（单项或全部资产）
36	  import     从另一数据目录批量导入资产及其工单、履历、请求绑定与保养计划（复制，源只读）
37	  help       显示本帮助
38	
39	各命令参数:
40	  register --asset-id 编号 --name 名称 --location 位置 [--data-dir 目录]
41	  list                                                        [--data-dir 目录]
42	  detail   --asset-id 编号                                    [--data-dir 目录]
43	  report   --asset-id 编号 --description 故障描述 --request-id 请求标识
44	                                                              [--data-dir 目录]
45	  assign   --ticket-id 工单编号 --assignee 维修人员 --note 说明  [--data-dir 目录]
46	  ticket   --ticket-id 工单编号                                 [--data-dir 目录]
47	  close    --ticket-id 工单编号 --repair-result 维修结果       [--data-dir 目录]
48	  cancel   --ticket-id 工单编号 --reason 取消理由              [--data-dir 目录]
49	  plan     --asset-id 编号 --content 保养内容 --first-due 首次到期日
50	           --interval-days 间隔天数                           [--data-dir 目录]
51	  maintain --asset-id 编号 --due 周期到期日 --done 实际完成日 --result 结果
52	                                                              [--data-dir 目录]
53	  due      --date 日期                                        [--data-dir 目录]
54	  history  --asset-id 编号                                    [--data-dir 目录]
55	  downtime --start 起点 --end 终点 [--asset-id 编号]          [--data-dir 目录]
56	  import   --source-dir 源目录 --asset-id 编号 [--asset-id 编号...]
57	                                                              [--data-dir 目录]
58	
59	通用参数:
60	  --data-dir 目录   本地数据目录，默认 ".caretrack"；不同目录数据互不影响，
61	                    目录不存在时会在首次成功写入时自动初始化
62	
63	业务规则:
64	  - 资产编号、名称、位置均不能为空；同一数据目录内资产编号唯一，新资产为“可用”。
65	  - 每项资产最多有一张未关闭工单；未知资产、空故障描述、资产已有未关闭工单时
66	    报修失败，不改变状态与履历。
67	  - --request-id 由调用方提供且非空，仅用于同一数据目录内的报修去重，不作为
68	    资产或工单编号：相同标识、资产、描述再次提交返回原工单及当前状态，不新增
69	    记录；同一标识搭配不同资产或描述将被拒绝；原工单关闭或取消后重放仍返回原工单，
70	    不重开旧单，也不影响新单。
71	  - 仅未关闭工单可派工：没有负责人时首次派工，已有负责人时转派给不同人员。
72	    维修人员标识只是本地文本记录（非人员账户），与派工说明均不能为空；
73	    成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为
74	    “未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单编号，
75	    不改变资产状态或报修请求绑定；未知工单、空人员或说明、重复派给当前
76	    人员、对已关闭或已取消工单派工均失败且不产生履历。工单关闭或取消后
77	    保留最后负责人与派工履历。
78	  - 仅未关闭工单可关闭，维修结果不能为空；未知工单、重复关闭均失败。
79	  - 仅未关闭工单可取消，取消理由不能为空；取消后工单进入“已取消”终态，保存取消
80	    理由与时间，资产恢复“可用”，可再次报修。取消不代表维修完成，不填写维修结果，
81	    不删除工单、履历或请求绑定，工单编号不回退也不复用；已取消工单不能关闭或再次
82	    取消，已关闭工单也不能取消。
83	  - 每项资产最多一个周期保养计划，建立后不可覆盖：保养内容非空，首次到期日为
84	    0001 至 9999 年的有效公历日期（YYYY-MM-DD），间隔天数为正整数；日期按日历日
85	    运算，不受时区与运行时刻影响。未知资产或已有计划时拒绝。资产详情显示保养
86	    内容、间隔与下一到期日，无计划时明确提示。
87	  - maintain 登记当前周期的保养完成：--due 所填周期到期日必须等于当前下一到期日
88	    （旧周期不能重复登记，也不能登记尚未到期的新周期），--done 实际完成日不得早于
89	    周期到期日，--result 结果非空；无计划时拒绝。成功后记录一次实际保养，下一到期
90	    日为首次到期日加整数倍间隔所得日期中严格晚于完成日的最早日期；延期跨过的
91	    周期不生成完成记录，也不改用完成日加间隔。若下一到期日超出 9999-12-31，整次
92	    拒绝。输出完成周期与下一到期日。
93	  - due 为只读查询：列出下一到期日不晚于 --date 的保养计划，显示资产编号、名称、
94	    保养内容和到期日，按到期日再按资产编号排序；无匹配明确提示。不写文件、不
95	    初始化目录、不推进计划。
96	  - 每个保养计划恰有一条含初始计划的建立履历，完成履历含周期到期日、实际完成日
97	    和结果；保养履历与维修履历按全库唯一履历序号共同展示操作时间及内容。维修中
98	    资产也可建立计划和登记完成：保养不创建或终结工单、不消耗工单编号，不改变
99	    资产状态、请求绑定或停机统计。
100	  - downtime 为只读统计，不写文件、不初始化目录、不追加履历。--start/--end 为
101	    带时区的 RFC3339 时刻（可含小数秒），起点须早于终点；窗口包含起点、不包含
102	    终点，按实际时刻比较。停机自工单报修履历时间起，至关闭或取消履历时间止
103	    （取消前的占用同样计入）；派工、转派不另起区间；未关闭工单暂算到窗口终点，
104	    不读取运行时刻，也不改变状态。只统计工单区间与窗口的交集，窗口外及零长度
105	    不贡献；同一资产多张工单的重叠交集取并集，不直接相加。每项资产合计后向下
106	    取整为秒，并输出全部所选资产秒数之和；没有停机的资产显示零。不给 --asset-id
107	    时统计全部资产并按编号字典序排列，空库明确提示无记录并显示零合计。若所选
108	    资产任一终结工单的结束履历时间早于报修履历时间（即使该单在窗口外、结束
109	    等于开始合法），整次统计失败，指出资产与工单，不输出部分结果。
110	  - import 把源数据目录中所选资产连同全部工单、报修请求绑定、履历与保养计划
111	    复制到目标目录（--data-dir）：源台账始终只读，同一台账不能导入自身；重复编号
112	    按一项处理。工单编号按源工单序号升序从目标下一序号重新分配，履历与请求绑定
113	    中的工单引用同步替换；履历在目标最大履历序号之后按源序号顺序分配新序号，保留
114	    原操作顺序与原时间（含小数秒）。保养计划与保养履历原样复制，内容、日期及完成
115	    链接续，目标已有计划不变。资产编号在目标已存在、或所选工单的任一请求标识已在
116	    目标绑定时整批拒绝，不覆盖、不合并。导入后可用原请求标识、资产与描述重放报修，
117	    返回映射后的工单及其当前状态；再次导入同一批资产按编号冲突拒绝。任何失败
118	    （源不存在、资产不存在、台账损坏、编号或履历序号容量不足、读写失败）都整批
119	    失败，两边原文件不变，不消耗目标编号。
120	
121	无参数、--help、-h 显示本帮助；参数错误或业务失败以非零退出码结束并说明原因。
122	参数错误退出码为 2；未知资产、上述时间异常及数据读取失败退出码为 1。
123	`
124	
125	type cmdOptions struct {
126		dataDir string
127	}
128	
129	func printHelp(w io.Writer) {
130		fmt.Fprint(w, helpText)
131	}
132	
133	func main() {
134		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
135	}
136	
137	func run(args []string, stdout, stderr io.Writer) int {
138		if len(args) == 0 {
139			printHelp(stdout)
140			return 0
141		}
142		switch args[0] {
143		case "--help", "-h", "help":
144			if len(args) > 1 {
145				fmt.Fprintf(stderr, "%s: help 不接受额外参数\n", appName)
146				return 2
147			}
148			printHelp(stdout)
149			return 0
150		}
151	
152		var err error
153		switch args[0] {
154		case "register":
155			err = cmdRegister(args[1:], stdout)
156		case "list":
157			err = cmdList(args[1:], stdout)
158		case "detail":
159			err = cmdDetail(args[1:], stdout)
160		case "report":
161			err = cmdReport(args[1:], stdout)
162		case "assign":
163			err = cmdAssign(args[1:], stdout)
164		case "ticket":
165			err = cmdTicket(args[1:], stdout)
166		case "close":
167			err = cmdClose(args[1:], stdout)
168		case "cancel":
169			err = cmdCancel(args[1:], stdout)
170		case "plan":
171			err = cmdPlan(args[1:], stdout)
172		case "maintain":
173			err = cmdMaintain(args[1:], stdout)
174		case "due":
175			err = cmdDue(args[1:], stdout)
176		case "history":
177			err = cmdHistory(args[1:], stdout)
178		case "downtime":
179			err = cmdDowntime(args[1:], stdout)
180		case "import":
181			err = cmdImport(args[1:], stdout)
182		default:
183			fmt.Fprintf(stderr, "%s: 未知命令 %q，使用 --help 查看帮助\n", appName, args[0])
184			return 2
185		}
186		if err != nil {
187			if errors.Is(err, flag.ErrHelp) {
188				return 0
189			}
190			var ue *usageError
191			if errors.As(err, &ue) {
192				fmt.Fprintf(stderr, "%s: %s\n", appName, ue.Error())
193				return 2
194			}
195			fmt.Fprintf(stderr, "%s: %s\n", appName, friendlyErr(err.Error()))
196			return 1
197		}
198		return 0
199	}
200	
201	// friendlyErr 去掉内部哨兵错误（errNotFound/errConflict）的英文前缀。
202	func friendlyErr(msg string) string {
203		for _, p := range []string{"not found: ", "conflict: "} {
204			if strings.HasPrefix(msg, p) {
205				return msg[len(p):]
206			}
207		}
208		return msg
209	}
210	
211	type usageError struct{ msg string }
212	
213	func (e *usageError) Error() string { return e.msg }
214	
215	// newFlagSet 为子命令准备参数解析器：--help/-h 输出帮助并返回 flag.ErrHelp，
216	// 其余参数错误转成 *usageError（退出码 2）。
217	func newFlagSet(name string, opts *cmdOptions) *flag.FlagSet {
218		fs := flag.NewFlagSet(name, flag.ContinueOnError)
219		fs.SetOutput(os.Stdout)
220		fs.Usage = func() {
221			fmt.Fprintf(os.Stdout, "用法: caretrack %s [参数]\n\n", name)
222			fs.PrintDefaults()
223		}
224		fs.StringVar(&opts.dataDir, "data-dir", ".caretrack", "本地数据目录")
225		return fs
226	}
227	
228	func parseFlags(fs *flag.FlagSet, args []string) error {
229		if err := fs.Parse(args); err != nil {
230			if errors.Is(err, flag.ErrHelp) {
231				return err
232			}
233			return &usageError{msg: err.Error()}
234		}
235		if fs.NArg() > 0 {
236			return &usageError{msg: fmt.Sprintf("命令 %s 不接受位置参数: %v", fs.Name(), fs.Args())}
237		}
238		return nil
239	}
240	
241	func requireFlag(fs *flag.FlagSet, value, flagName string) error {
242		if value == "" {
243			return &usageError{msg: fmt.Sprintf("命令 %s 缺少必填参数 --%s", fs.Name(), flagName)}
244		}
245		return nil
246	}
247	
248	func cmdRegister(args []string, w io.Writer) error {
249		var opts cmdOptions
250		var id, name, location string
251		fs := newFlagSet("register", &opts)
252		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填，同一数据目录内唯一）")
253		fs.StringVar(&name, "name", "", "资产名称（必填）")
254		fs.StringVar(&location, "location", "", "资产位置（必填）")
255		if err := parseFlags(fs, args); err != nil {
256			return err
257		}
258		if err := requireFlag(fs, id, "asset-id"); err != nil {
259			return err
260		}
261		if err := requireFlag(fs, name, "name"); err != nil {
262			return err
263		}
264		if err := requireFlag(fs, location, "location"); err != nil {
265			return err
266		}
267	
268		s, err := openStore(opts.dataDir)
269		if err != nil {
270			return err
271		}
272		asset, err := s.registerAsset(id, name, location)
273		if err != nil {
274			return err
275		}
276		if err := s.save(); err != nil {
277			return err
278		}
279		fmt.Fprintf(w, "已登记资产 %s\n", asset.ID)
280		fmt.Fprintf(w, "名称: %s\n", asset.Name)
281		fmt.Fprintf(w, "位置: %s\n", asset.Location)
282		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
283		return nil
284	}
285	
286	func cmdList(args []string, w io.Writer) error {
287		var opts cmdOptions
288		fs := newFlagSet("list", &opts)
289		if err := parseFlags(fs, args); err != nil {
290			return err
291		}
292		s, err := openStore(opts.dataDir)
293		if err != nil {
294			return err
295		}
296		assets := s.data.Assets
297		if len(assets) == 0 {
298			fmt.Fprintln(w, "没有记录。")
299			return nil
300		}
301		fmt.Fprintf(w, "共 %d 项资产:\n", len(assets))
302		for _, a := range assets {
303			fmt.Fprintf(w, "%s\t%s\t%s\t%s\n", a.ID, a.Name, a.Location, a.Status)
304		}
305		return nil
306	}
307	
308	func cmdDetail(args []string, w io.Writer) error {
309		var opts cmdOptions
310		var id string
311		fs := newFlagSet("detail", &opts)
312		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
313		if err := parseFlags(fs, args); err != nil {
314			return err
315		}
316		if err := requireFlag(fs, id, "asset-id"); err != nil {
317			return err
318		}
319		s, err := openStore(opts.dataDir)
320		if err != nil {
321			return err
322		}
323		asset := s.findAsset(id)
324		if asset == nil {
325			return fmt.Errorf("未知资产编号 %q", id)
326		}
327		openTicket := s.openTicketOf(asset.ID)
328		fmt.Fprintf(w, "资产编号: %s\n", asset.ID)
329		fmt.Fprintf(w, "名称: %s\n", asset.Name)
330		fmt.Fprintf(w, "位置: %s\n", asset.Location)
331		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
332		if openTicket == nil {
333			fmt.Fprintln(w, "未关闭工单: 无")
334		} else {
335			fmt.Fprintf(w, "未关闭工单: %s\n", openTicket.ID)
336			fmt.Fprintf(w, "工单负责人: %s\n", assigneeDisplay(openTicket.Assignee))
337		}
338		plan := s.findPlan(asset.ID)
339		if plan == nil {
340			fmt.Fprintln(w, "保养计划: 无")
341		} else {
342			fmt.Fprintf(w, "保养内容: %s\n", plan.Content)
343			fmt.Fprintf(w, "保养间隔: 每 %d 天\n", plan.IntervalDays)
344			fmt.Fprintf(w, "下一到期日: %s\n", plan.NextDue)
345		}
346		return nil
347	}
348	
349	// assigneeDisplay 把空负责人显示为“未派工”。
350	func assigneeDisplay(assignee string) string {
351		if assignee == "" {
352			return "未派工"
353		}
354		return assignee
355	}
356	
357	func cmdReport(args []string, w io.Writer) error {
358		var opts cmdOptions
359		var assetID, description, requestID string
360		fs := newFlagSet("report", &opts)
361		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（必填）")
362		fs.StringVar(&description, "description", "", "故障描述（必填）")
363		fs.StringVar(&requestID, "request-id", "", "调用方提供的非空请求标识，用于报修去重（必填）")
364		if err := parseFlags(fs, args); err != nil {
365			return err
366		}
367		if err := requireFlag(fs, assetID, "asset-id"); err != nil {
368			return err
369		}
370		if err := requireFlag(fs, description, "description"); err != nil {
371			return err
372		}
373		if err := requireFlag(fs, requestID, "request-id"); err != nil {
374			return err
375		}
376	
377		s, err := openStore(opts.dataDir)
378		if err != nil {
379			return err
380		}
381		ticket, replayed, err := s.report(assetID, description, requestID)
382		if err != nil {
383			return err
384		}
385		if !replayed {
386			if err := s.save(); err != nil {
387				return err
388			}
389			fmt.Fprintf(w, "工单编号: %s\n", ticket.ID)
390		} else {
391			fmt.Fprintf(w, "该请求标识已提交过，返回原工单，未重复创建。\n")
392			fmt.Fprintf(w, "工单编号: %s（既有工单）\n", ticket.ID)
393		}
394		fmt.Fprintf(w, "资产编号: %s\n", ticket.AssetID)
395		fmt.Fprintf(w, "工单状态: %s\n", ticket.Status)
396		return nil
397	}
398	
399	func cmdAssign(args []string, w io.Writer) error {
400		var opts cmdOptions
401		var ticketID, assignee, note string
