531	// cmdPlan 为资产建立唯一的周期保养计划。日期与间隔的参数错误为退出码 2；
532	// 未知资产、已有计划等业务失败为退出码 1。
533	func cmdPlan(args []string, w io.Writer) error {
534		var opts cmdOptions
535		var assetID, content, firstDue string
536		var interval int
537		fs := newFlagSet("plan", &opts)
538		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（必填）")
539		fs.StringVar(&content, "content", "", "保养内容（必填，非空）")
540		fs.StringVar(&firstDue, "first-due", "", "首次到期日（必填，YYYY-MM-DD，0001 至 9999 年的有效公历日期）")
541		fs.IntVar(&interval, "interval-days", 0, "保养间隔天数（必填，正整数）")
542		if err := parseFlags(fs, args); err != nil {
543			return err
544		}
545		if err := requireFlag(fs, assetID, "asset-id"); err != nil {
546			return err
547		}
548		if err := requireFlag(fs, content, "content"); err != nil {
549			return err
550		}
551		if err := requireFlag(fs, firstDue, "first-due"); err != nil {
552			return err
553		}
554		if _, err := parseDate(firstDue); err != nil {
555			return &usageError{msg: fmt.Sprintf("--first-due 无效：%s", err)}
556		}
557		if interval < 1 {
558			return &usageError{msg: "--interval-days 须为正整数"}
559		}
