571		}
572		fmt.Fprintf(w, "已为资产 %s 建立保养计划。\n", p.AssetID)
573		fmt.Fprintf(w, "保养内容: %s\n", p.Content)
574		fmt.Fprintf(w, "保养间隔: 每 %d 天\n", p.IntervalDays)
575		fmt.Fprintf(w, "首次到期日: %s\n", p.FirstDue)
576		return nil
577	}
