579	// cmdMaintain 登记当前周期的保养完成并推进下一到期日。
580	func cmdMaintain(args []string, w io.Writer) error {
581		var opts cmdOptions
582		var assetID, due, done, result string
583		fs := newFlagSet("maintain", &opts)
584		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（必填）")
585		fs.StringVar(&due, "due", "", "所完成周期的到期日（必填，YYYY-MM-DD，须等于当前下一到期日）")
586		fs.StringVar(&done, "done", "", "实际完成日（必填，YYYY-MM-DD，不得早于周期到期日）")
587		fs.StringVar(&result, "result", "", "保养结果（必填，非空）")
588		if err := parseFlags(fs, args); err != nil {
589			return err
590		}
591		if err := requireFlag(fs, assetID, "asset-id"); err != nil {
592			return err
593		}
594		if err := requireFlag(fs, due, "due"); err != nil {
595			return err
596		}
597		if err := requireFlag(fs, done, "done"); err != nil {
598			return err
599		}
600		if err := requireFlag(fs, result, "result"); err != nil {
601			return err
602		}
603		if _, err := parseDate(due); err != nil {
604			return &usageError{msg: fmt.Sprintf("--due 无效：%s", err)}
605		}
606		if _, err := parseDate(done); err != nil {
607			return &usageError{msg: fmt.Sprintf("--done 无效：%s", err)}
608		}
609	
610		s, err := openStore(opts.dataDir)
611		if err != nil {
612			return err
613		}
614		p, next, err := s.completePlan(assetID, due, done, result)
615		if err != nil {
616			return err
617		}
618		if err := s.save(); err != nil {
619			return err
620		}
621		fmt.Fprintf(w, "资产 %s 已完成周期 %s 的保养。\n", p.AssetID, due)
622		fmt.Fprintf(w, "实际完成日: %s\n", done)
623		fmt.Fprintf(w, "下一到期日: %s\n", next)
624		return nil
625	}
626	
627	// cmdDue 为只读的到期查询：列出下一到期日不晚于指定日期的保养计划。
628	// 不写文件、不初始化目录、不推进计划。
629	func cmdDue(args []string, w io.Writer) error {
630		var opts cmdOptions
631		var date string
632		fs := newFlagSet("due", &opts)
633		fs.StringVar(&date, "date", "", "查询截止日期（必填，YYYY-MM-DD；列出下一到期日不晚于该日的计划）")
634		if err := parseFlags(fs, args); err != nil {
635			return err
636		}
637		if err := requireFlag(fs, date, "date"); err != nil {
638			return err
639		}
640		if _, err := parseDate(date); err != nil {
