642		}
643	
644		s, err := openStore(opts.dataDir)
645		if err != nil {
646			return err
647		}
648		rows := s.duePlans(date)
649		if len(rows) == 0 {
650			fmt.Fprintf(w, "截至 %s 没有到期的保养计划。\n", date)
651			return nil
652		}
653		fmt.Fprintf(w, "截至 %s 共 %d 项到期保养计划:\n", date, len(rows))
654		for _, r := range rows {
655			fmt.Fprintf(w, "%s\t%s\t%s\t%s\n", r.AssetID, r.Name, r.Content, r.Due)
656		}
