659	
660	func cmdHistory(args []string, w io.Writer) error {
661		var opts cmdOptions
662		var id string
663		fs := newFlagSet("history", &opts)
664		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
665		if err := parseFlags(fs, args); err != nil {
666			return err
667		}
668		if err := requireFlag(fs, id, "asset-id"); err != nil {
669			return err
670		}
671		s, err := openStore(opts.dataDir)
672		if err != nil {
673			return err
674		}
675		if s.findAsset(id) == nil {
676			return fmt.Errorf("未知资产编号 %q", id)
677		}
678		events := s.eventsOf(id)
679		if len(events) == 0 {
680			fmt.Fprintf(w, "资产 %s 暂无维修履历。\n", id)
681			return nil
682		}
683		fmt.Fprintf(w, "资产 %s 维修履历（共 %d 条）:\n", id, len(events))
684		for _, e := range events {
685			ts := e.Time.Format("2006-01-02T15:04:05Z07:00")
686			switch e.Kind {
687			case eventAssign:
688				fmt.Fprintf(w, "[%s] %s 工单 %s: %s -> %s（%s）\n",
689					ts, e.Kind, e.TicketID, assigneeDisplay(e.From), e.To, e.Content)
690			case eventPlanCreate:
691				fmt.Fprintf(w, "[%s] %s: %s（首次到期日 %s，每 %d 天）\n",
692					ts, e.Kind, e.Content, e.Due, e.Interval)
693			case eventPlanDone:
694				fmt.Fprintf(w, "[%s] %s: 周期到期日 %s，实际完成日 %s，%s\n",
695					ts, e.Kind, e.Due, e.Done, e.Content)
696			default:
697				fmt.Fprintf(w, "[%s] %s 工单 %s: %s\n", ts, e.Kind, e.TicketID, e.Content)
698			}
699		}
700		return nil
701	}
702	
703	// cmdDowntime 为只读的停机时长统计：先经 openStore 完成整库一致性检查，
704	// 再计算窗口内的停机秒数。无论成功或失败都不保存，因此不写文件、不初始化
705	// 目录、不追加履历、不消耗编号，也不改变报修请求绑定。
706	func cmdDowntime(args []string, w io.Writer) error {
707		var opts cmdOptions
708		var startText, endText, assetID string
709		fs := newFlagSet("downtime", &opts)
710		fs.StringVar(&startText, "start", "", "窗口起点（必填，带时区的 RFC3339 时刻，可含小数秒；包含）")
711		fs.StringVar(&endText, "end", "", "窗口终点（必填，带时区的 RFC3339 时刻，可含小数秒；不包含）")
712		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（可选；缺省统计全部资产）")
713		if err := parseFlags(fs, args); err != nil {
714			return err
715		}
716		if err := requireFlag(fs, startText, "start"); err != nil {
717			return err
718		}
719		if err := requireFlag(fs, endText, "end"); err != nil {
720			return err
721		}
722		start, err := time.Parse(time.RFC3339, startText)
723		if err != nil {
724			return &usageError{msg: fmt.Sprintf("--start 不是带时区的 RFC3339 时刻 %q: %s", startText, err)}
725		}
726		end, err := time.Parse(time.RFC3339, endText)
727		if err != nil {
728			return &usageError{msg: fmt.Sprintf("--end 不是带时区的 RFC3339 时刻 %q: %s", endText, err)}
729		}
730		if !start.Before(end) {
731			return &usageError{msg: fmt.Sprintf("--start（%s）须早于 --end（%s）", startText, endText)}
732		}
733	
734		// openStore 已先做整库一致性检查：损坏或关联矛盾按原规则拒绝（退出码 1）。
735		s, err := openStore(opts.dataDir)
736		if err != nil {
737			return err
738		}
739	
740		var ids []string
741		if assetID != "" {
742			// 未知资产在统计前拒绝（退出码 1）。
743			if s.findAsset(assetID) == nil {
744				return fmt.Errorf("未知资产编号 %q", assetID)
745			}
746			ids = []string{assetID}
747		} else {
748			ids = s.allAssetIDs()
749			if len(ids) == 0 {
750				fmt.Fprintln(w, "没有记录。")
751				fmt.Fprintln(w, "合计: 0 秒")
752				return nil
753			}
754		}
755	
756		// 先算完全部结果再输出：任一资产存在时间异常时整体失败，不输出部分结果。
757		results, err := s.downtimeForAssets(ids, start, end)
758		if err != nil {
759			return err
760		}
761		var total int64
762		if len(results) == 1 {
763			r := results[0]
764			fmt.Fprintf(w, "资产编号: %s\n", r.AssetID)
765			fmt.Fprintf(w, "名称: %s\n", r.Name)
766			fmt.Fprintf(w, "停机秒数: %d\n", r.Seconds)
767			total = r.Seconds
768		} else {
769			fmt.Fprintf(w, "共 %d 项资产:\n", len(results))
770			for _, r := range results {
771				fmt.Fprintf(w, "%s\t%s\t%d\n", r.AssetID, r.Name, r.Seconds)
772				total += r.Seconds
773			}
774		}
775		fmt.Fprintf(w, "合计: %d 秒\n", total)
776		return nil
777	}
