1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"time"
15	)
16	
17	// 资产状态、工单状态与履历类型。
18	const (
19		statusAvailable = "可用"
20		statusRepairing = "维修中"
21		ticketOpen      = "未关闭"
22		ticketClosed    = "已关闭"
23		ticketCancelled = "已取消"
24	
25		eventReport = "报修"
26		eventClose  = "关闭"
27		eventCancel = "取消"
28		eventAssign = "派工"
29	
30		eventPlanCreate = "保养建立"
31		eventPlanDone   = "保养完成"
32	
33		storeVersion = 1
34		dataFileName = "caretrack.json"
35	)
36	
37	var (
38		errNotFound = errors.New("not found")
39		errConflict = errors.New("conflict")
40	)
41	
42	// Asset 为登记的设备资产，ID 即企业资产编号。
43	type Asset struct {
44		ID       string `json:"id"`
45		Name     string `json:"name"`
46		Location string `json:"location"`
47		Status   string `json:"status"`
48	}
49	
50	// Ticket 为维修工单。Assignee 为当前（或终结前最后）负责人，空表示未派工；
51	// AssignedAt/AssignNote 为最近一次派工的变更时间与说明。
52	type Ticket struct {
53		ID           string `json:"id"`
54		AssetID      string `json:"asset_id"`
55		Description  string `json:"description"`
56		RequestID    string `json:"request_id"`
57		Status       string `json:"status"`
58		Result       string `json:"result,omitempty"`
59		CreatedAt    string `json:"created_at"`
60		ClosedAt     string `json:"closed_at,omitempty"`
61		CancelReason string `json:"cancel_reason,omitempty"`
62		CancelledAt  string `json:"cancelled_at,omitempty"`
63		Assignee     string `json:"assignee,omitempty"`
64		AssignedAt   string `json:"assigned_at,omitempty"`
65		AssignNote   string `json:"assign_note,omitempty"`
66	}
67	
68	// Event 为履历条目（报修/派工/关闭/取消/保养建立/保养完成），Seq 决定操作发生顺序。
69	// From/To 仅派工履历使用：原负责人（首次派工为空，展示为“未派工”）与新负责人。
70	// Due/Done/Interval 仅保养履历使用：建立履历含首次到期日（Due）与间隔天数
71	// （Interval），完成履历含周期到期日（Due）与实际完成日（Done）。
72	type Event struct {
73		Seq      int       `json:"-"`
74		AssetID  string    `json:"-"`
75		TicketID string    `json:"-"`
76		Kind     string    `json:"-"`
77		Content  string    `json:"-"`
78		From     string    `json:"-"`
79		To       string    `json:"-"`
80		Due      string    `json:"-"`
81		Done     string    `json:"-"`
82		Interval int       `json:"-"`
83		Time     time.Time `json:"-"`
84	}
85	
86	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
87	type eventJSON struct {
88		Seq      int    `json:"seq"`
89		AssetID  string `json:"asset_id"`
90		TicketID string `json:"ticket_id,omitempty"`
91		Kind     string `json:"kind"`
92		Content  string `json:"content"`
93		From     string `json:"from,omitempty"`
94		To       string `json:"to,omitempty"`
95		Due      string `json:"due,omitempty"`
96		Done     string `json:"done,omitempty"`
97		Interval int    `json:"interval,omitempty"`
98		Time     string `json:"time"`
99	}
100	
101	func (e Event) toJSON() eventJSON {
102		return eventJSON{
103			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
104			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
105			Due: e.Due, Done: e.Done, Interval: e.Interval,
106			// RFC3339Nano 保留小数秒精度；整秒时输出与 RFC3339 完全一致，
107			// 因此既有整秒台账的字节表示不变，而旧库中带小数秒的履历时间
108			// 在重新保存（含导入合并后的提交）时也不会被截断。
109			Time: e.Time.Format(time.RFC3339Nano),
110		}
111	}
112	
113	func (e eventJSON) toEvent() (Event, error) {
114		t, err := time.Parse(time.RFC3339, e.Time)
115		if err != nil {
116			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
117		}
118		return Event{
119			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
120			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
121			Due: e.Due, Done: e.Done, Interval: e.Interval, Time: t,
122		}, nil
123	}
124	
125	// requestBinding 记录请求标识与具体报修的绑定，用于去重与冲突拒绝；
126	// 它既不是资产编号也不是工单编号。
127	type requestBinding struct {
128		RequestID   string `json:"request_id"`
129		AssetID     string `json:"asset_id"`
130		Description string `json:"description"`
131		TicketID    string `json:"ticket_id"`
132	}
133	
134	// storeData 是一次成功写操作共同生效的完整业务数据。
135	type storeData struct {
136		Version       int              `json:"version"`
137		Assets        []*Asset         `json:"assets"`
138		Tickets       []*Ticket        `json:"tickets"`
139		Events        []Event          `json:"-"`
140		EventsJSON    []eventJSON      `json:"events"`
141		Requests      []requestBinding `json:"requests"`
142		Plans         []*Plan          `json:"plans"`
143		NextTicketSeq int              `json:"next_ticket_seq"`
144	}
145	
146	type store struct {
147		dir  string
148		data *storeData
149		now  func() time.Time
150	}
151	
152	func newStoreData() *storeData {
153		return &storeData{
154			Version:       storeVersion,
155			Assets:        []*Asset{},
156			Tickets:       []*Ticket{},
157			Events:        []Event{},
158			EventsJSON:    []eventJSON{},
159			Requests:      []requestBinding{},
160			Plans:         []*Plan{},
161			NextTicketSeq: 1,
162		}
163	}
164	
165	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
166	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
167	func openStore(dir string) (*store, error) {
168		return loadStore(dir, true)
169	}
170	
171	// openSourceStore 以只读用途打开导入源数据目录：与 openStore 做同样的整库
172	// 一致性检查，但源台账必须已存在——不存在时报错，绝不能当空库初始化。
173	func openSourceStore(dir string) (*store, error) {
174		return loadStore(dir, false)
175	}
176	
177	func loadStore(dir string, allowMissing bool) (*store, error) {
178		path := filepath.Join(dir, dataFileName)
179		raw, err := os.ReadFile(path)
180		if err != nil {
181			if errors.Is(err, os.ErrNotExist) {
182				if allowMissing {
183					return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
184				}
185				return nil, fmt.Errorf("源数据文件 %s 不存在：源台账必须已存在，不能当空库处理", path)
186			}
187			return nil, fmt.Errorf("读取数据文件失败: %w", err)
188		}
189		if len(bytes.TrimSpace(raw)) == 0 {
190			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
191		}
192		var d storeData
193		if err := json.Unmarshal(raw, &d); err != nil {
194			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
195		}
196		if d.EventsJSON != nil {
197			d.Events = make([]Event, len(d.EventsJSON))
198			for i, ej := range d.EventsJSON {
199				ev, err := ej.toEvent()
200				if err != nil {
201					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
202				}
203				d.Events[i] = ev
204			}
205		}
206		// 无保养字段的有效旧库直接使用：缺省视为没有任何保养计划。
207		if d.Plans == nil {
208			d.Plans = []*Plan{}
209		}
210		if err := validateData(&d); err != nil {
211			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
212		}
213		return &store{dir: dir, data: &d, now: time.Now}, nil
214	}
215	
216	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
217	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
218	func parseTicketSeq(id string) (int, bool) {
219		if !strings.HasPrefix(id, "T") {
220			return 0, false
221		}
222		n, err := strconv.Atoi(id[1:])
223		if err != nil || n < 1 {
224			return 0, false
225		}
226		if fmt.Sprintf("T%04d", n) != id {
227			return 0, false
228		}
229		return n, true
230	}
231	
232	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
233	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
234	// 不做任何修复：不补字段、不重编号、不删除记录。
235	func validateData(d *storeData) error {
236		if d.Version != storeVersion {
237			return fmt.Errorf("不支持的数据版本 %d", d.Version)
238		}
239		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil || d.Plans == nil {
240			return errors.New("缺少必要的数据段")
241		}
242		assets := map[string]*Asset{}
243		for _, a := range d.Assets {
244			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
245				return errors.New("数据矛盾：存在字段不完整的资产记录")
246			}
247			if a.Status != statusAvailable && a.Status != statusRepairing {
248				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
249			}
250			if assets[a.ID] != nil {
251				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
252			}
253			assets[a.ID] = a
254		}
255		tickets := map[string]*Ticket{}
256		maxTicketSeq := 0
257		for _, t := range d.Tickets {
258			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
259				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
260			}
261			n, ok := parseTicketSeq(t.ID)
262			if !ok {
263				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
264			}
265			if n > maxTicketSeq {
266				maxTicketSeq = n
267			}
268			if t.Status != ticketOpen && t.Status != ticketClosed && t.Status != ticketCancelled {
269				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
270			}
271			if assets[t.AssetID] == nil {
272				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
273			}
274			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
275				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
276			}
277			if t.Status == ticketCancelled && (t.CancelReason == "" || t.CancelledAt == "") {
278				return fmt.Errorf("状态矛盾：已取消工单 %s 缺少取消理由或取消时间", t.ID)
279			}
280			if t.Status != ticketClosed && (t.Result != "" || t.ClosedAt != "") {
281				return fmt.Errorf("状态矛盾：非已关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
282			}
283			if t.Status != ticketCancelled && (t.CancelReason != "" || t.CancelledAt != "") {
284				return fmt.Errorf("状态矛盾：非已取消工单 %s 不应带有取消理由或取消时间", t.ID)
285			}
286			if t.Assignee == "" {
287				if t.AssignedAt != "" || t.AssignNote != "" {
288					return fmt.Errorf("状态矛盾：未派工工单 %s 不应带有派工时间或派工说明", t.ID)
289				}
290			} else if t.AssignedAt == "" || t.AssignNote == "" {
291				return fmt.Errorf("状态矛盾：已派工工单 %s 缺少派工时间或派工说明", t.ID)
292			}
293			if tickets[t.ID] != nil {
294				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
295			}
296			tickets[t.ID] = t
297		}
298		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
299		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
300			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
301				d.NextTicketSeq, maxTicketSeq)
302		}
303		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
304		boundReq := map[string]bool{}
305		boundTicket := map[string]bool{}
306		for _, r := range d.Requests {
307			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
308				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
309			}
310			if boundReq[r.RequestID] {
311				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
312			}
313			boundReq[r.RequestID] = true
314			t := tickets[r.TicketID]
315			if t == nil {
316				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
317			}
318			if t.RequestID != r.RequestID {
319				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
320					r.TicketID, t.RequestID, r.RequestID)
321			}
322			if r.AssetID != t.AssetID || r.Description != t.Description {
323				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
324					r.RequestID, t.ID)
325			}
326			boundTicket[r.TicketID] = true
327		}
328		for _, t := range d.Tickets {
329			if !boundTicket[t.ID] {
330				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
331			}
332		}
333		// 状态：每项资产最多一张未关闭工单，有则“维修中”，无则“可用”。
334		openCount := map[string]int{}
335		for _, t := range d.Tickets {
336			if t.Status == ticketOpen {
337				openCount[t.AssetID]++
338			}
339		}
340		for _, a := range d.Assets {
341			c := openCount[a.ID]
342			if c > 1 {
343				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，最多允许一张", a.ID, c)
344			}
345			want := statusAvailable
346			if c == 1 {
347				want = statusRepairing
348			}
349			if a.Status != want {
350				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，状态应为 %s，实际为 %s",
351					a.ID, c, want, a.Status)
352			}
353		}
354		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
355		seenSeq := map[int]bool{}
356		reportSeq := map[string]int{}
357		closeSeq := map[string]int{}
358		cancelSeq := map[string]int{}
359		reportCount := map[string]int{}
360		closeCount := map[string]int{}
361		cancelCount := map[string]int{}
362		for i := range d.Events {
363			e := &d.Events[i]
364			if e.Seq < 1 {
365				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
366			}
367			if seenSeq[e.Seq] {
368				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
369			}
370			seenSeq[e.Seq] = true
371			if e.AssetID == "" || e.Kind == "" || e.Content == "" {
372				return errors.New("履历矛盾：存在字段不完整的履历记录")
373			}
374			if e.Kind == eventPlanCreate || e.Kind == eventPlanDone {
375				// 保养履历：不属于任何工单，不携带派工字段；日期与间隔在此核对，
376				// 建立及完成链的接续在下方按序号重放时核对。
377				if e.TicketID != "" || e.From != "" || e.To != "" {
378					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号或派工人员字段", e.Seq, e.Kind)
379				}
380				due, err := parseDate(e.Due)
381				if err != nil {
382					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录到期日无效", e.Seq, e.Kind)
383				}
384				if e.Kind == eventPlanCreate {
385					if e.Done != "" {
386						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录不应带有完成日", e.Seq)
387					}
388					if e.Interval < 1 {
389						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录间隔天数须为正整数", e.Seq)
390					}
391				} else {
392					if e.Interval != 0 {
393						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录不应带有间隔天数", e.Seq)
394					}
395					done, err := parseDate(e.Done)
396					if err != nil {
397						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录完成日无效", e.Seq)
398					}
399					if done < due {
400						return fmt.Errorf("履历矛盾：履历序号 %d 的完成日早于周期到期日", e.Seq)
401					}
402				}
403				continue
404			}
405			if e.TicketID == "" {
406				return errors.New("履历矛盾：存在字段不完整的履历记录")
407			}
408			if e.Due != "" || e.Done != "" || e.Interval != 0 {
409				return fmt.Errorf("履历矛盾：履历序号 %d 的维修履历不应带有保养字段", e.Seq)
410			}
411			if e.Kind != eventAssign && (e.From != "" || e.To != "") {
412				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有派工人员字段", e.Seq, e.Kind)
413			}
414			if e.Kind == eventAssign {
415				if e.To == "" {
416					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录缺少新负责人", e.Seq)
417				}
418				if e.From == e.To {
419					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录新负责人与原负责人相同", e.Seq)
420				}
421			}
422			t := tickets[e.TicketID]
423			if t == nil || assets[e.AssetID] == nil {
424				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
425			}
426			if e.AssetID != t.AssetID {
427				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
428					e.Seq, e.AssetID, t.ID, t.AssetID)
429			}
430			switch e.Kind {
431			case eventReport:
432				if e.Content != t.Description {
433					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
434				}
435				reportCount[t.ID]++
436				reportSeq[t.ID] = e.Seq
437			case eventClose:
438				if e.Content != t.Result {
439					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
440				}
441				closeCount[t.ID]++
442				closeSeq[t.ID] = e.Seq
443			case eventCancel:
444				if e.Content != t.CancelReason {
445					return fmt.Errorf("履历矛盾：工单 %s 的取消履历内容与取消理由不一致", t.ID)
446				}
447				cancelCount[t.ID]++
448				cancelSeq[t.ID] = e.Seq
449			case eventAssign:
450				// 内容即派工说明（非空已检查）；派工链的接续与工单负责人一致性
451				// 在下方按序号重放时核对。
452			default:
453				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
454			}
455		}
456		for _, t := range d.Tickets {
457			if reportCount[t.ID] != 1 {
458				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
459			}
460			if t.Status == ticketClosed {
461				if closeCount[t.ID] != 1 {
462					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
463				}
464				if closeSeq[t.ID] <= reportSeq[t.ID] {
465					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
466						t.ID, closeSeq[t.ID], reportSeq[t.ID])
467				}
468			} else if closeCount[t.ID] != 0 {
469				return fmt.Errorf("履历矛盾：非已关闭工单 %s 不得有关闭履历", t.ID)
470			}
471			if t.Status == ticketCancelled {
472				if cancelCount[t.ID] != 1 {
473					return fmt.Errorf("履历矛盾：已取消工单 %s 应有恰一条取消履历，实际 %d 条", t.ID, cancelCount[t.ID])
474				}
475				if cancelSeq[t.ID] <= reportSeq[t.ID] {
476					return fmt.Errorf("履历矛盾：工单 %s 的取消履历（序号 %d）不在报修履历（序号 %d）之后",
477						t.ID, cancelSeq[t.ID], reportSeq[t.ID])
478				}
479			} else if cancelCount[t.ID] != 0 {
480				return fmt.Errorf("履历矛盾：非已取消工单 %s 不得有取消履历", t.ID)
481			}
482		}
483		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
484		// 同一资产的上一张工单必须先关闭或取消才可产生下一张报修。
485		sorted := make([]Event, len(d.Events))
486		copy(sorted, d.Events)
487		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
488		derivedTicket := map[string]string{}
489		derivedOpen := map[string]string{}
490		derivedAssignee := map[string]string{}
491		derivedNote := map[string]string{}
492		for _, e := range sorted {
493			switch e.Kind {
494			case eventReport:
495				if derivedTicket[e.TicketID] != "" {
496					return fmt.Errorf("履历矛盾：工单 %s 被重复报修", e.TicketID)
497				}
498				if prev := derivedOpen[e.AssetID]; prev != "" {
499					return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未结束就产生了工单 %s 的报修",
500						e.AssetID, prev, e.TicketID)
501				}
502				derivedTicket[e.TicketID] = ticketOpen
503				derivedOpen[e.AssetID] = e.TicketID
504			case eventAssign:
505				if derivedTicket[e.TicketID] != ticketOpen {
506					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现派工履历", e.TicketID)
507				}
508				if e.From != derivedAssignee[e.TicketID] {
509					return fmt.Errorf("履历矛盾：工单 %s 的派工履历（序号 %d）原负责人 %q 与上次记录不接续",
510						e.TicketID, e.Seq, e.From)
511				}
512				derivedAssignee[e.TicketID] = e.To
513				derivedNote[e.TicketID] = e.Content
514			case eventClose:
515				if derivedTicket[e.TicketID] != ticketOpen {
516					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现关闭履历", e.TicketID)
517				}
518				derivedTicket[e.TicketID] = ticketClosed
519				delete(derivedOpen, e.AssetID)
520			case eventCancel:
521				if derivedTicket[e.TicketID] != ticketOpen {
522					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现取消履历", e.TicketID)
523				}
524				derivedTicket[e.TicketID] = ticketCancelled
525				delete(derivedOpen, e.AssetID)
526			}
527		}
528		for _, t := range d.Tickets {
529			if derivedTicket[t.ID] != t.Status {
530				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
531					t.ID, derivedTicket[t.ID], t.Status)
532			}
533			// 由履历推出的最后负责人须与工单记录一致；无派工履历则必须未派工。
534			if derivedAssignee[t.ID] != t.Assignee {
535				return fmt.Errorf("状态矛盾：按履历推出工单 %s 最后负责人为 %q，与保存的 %q 不符",
536					t.ID, derivedAssignee[t.ID], t.Assignee)
537			}
538			if t.Assignee != "" && derivedNote[t.ID] != t.AssignNote {
539				return fmt.Errorf("状态矛盾：工单 %s 保存的派工说明与最后一次派工履历不一致", t.ID)
540			}
541		}
542		for _, a := range d.Assets {
543			want := statusAvailable
544			if derivedOpen[a.ID] != "" {
545				want = statusRepairing
546			}
547			if a.Status != want {
548				return fmt.Errorf("状态矛盾：按履历推进得到资产 %s 状态为 %s，与保存的 %s 不符",
549					a.ID, want, a.Status)
550			}
551		}
552		// 保养计划：归属存在的资产、每项资产最多一个、日期有效、间隔为正整数。
553		plans := map[string]*Plan{}
554		for _, p := range d.Plans {
555			if p == nil || p.AssetID == "" || p.Content == "" {
556				return errors.New("数据矛盾：存在字段不完整的保养计划")
557			}
558			if assets[p.AssetID] == nil {
559				return fmt.Errorf("数据矛盾：保养计划引用了不存在的资产 %s", p.AssetID)
560			}
561			if plans[p.AssetID] != nil {
562				return fmt.Errorf("数据矛盾：资产 %s 有多个保养计划，最多允许一个", p.AssetID)
563			}
564			if _, err := parseDate(p.FirstDue); err != nil {
565				return fmt.Errorf("数据矛盾：资产 %s 保养计划的首次到期日无效", p.AssetID)
566			}
567			if p.IntervalDays < 1 {
568				return fmt.Errorf("数据矛盾：资产 %s 保养计划的间隔天数须为正整数", p.AssetID)
569			}
570			if _, err := parseDate(p.NextDue); err != nil {
571				return fmt.Errorf("数据矛盾：资产 %s 保养计划的下一到期日无效", p.AssetID)
572			}
573			plans[p.AssetID] = p
574		}
575		// 保养履历链：每个计划恰有一条建立履历（内容、首次到期日、间隔与计划一致），
576		// 完成履历按序号接续（周期到期日须等于当前下一到期日，完成日不早于它），
577		// 由履历推出的下一到期日须与计划保存的一致。没有计划的资产不得有保养履历。
578		maintCreate := map[string]int{}
579		derivedDue := map[string]string{}
580		for _, e := range sorted {
581			if e.Kind != eventPlanCreate && e.Kind != eventPlanDone {
582				continue
583			}
584			p := plans[e.AssetID]
585			if p == nil {
586				return fmt.Errorf("履历矛盾：资产 %s 没有保养计划，却存在保养履历（序号 %d）", e.AssetID, e.Seq)
587			}
588			if e.Kind == eventPlanCreate {
589				if maintCreate[e.AssetID] != 0 {
590					return fmt.Errorf("履历矛盾：资产 %s 有多条保养建立履历", e.AssetID)
591				}
592				maintCreate[e.AssetID] = e.Seq
593				if e.Content != p.Content || e.Due != p.FirstDue || e.Interval != p.IntervalDays {
594					return fmt.Errorf("履历矛盾：资产 %s 的保养建立履历与计划内容、首次到期日或间隔不一致", e.AssetID)
595				}
596				derivedDue[e.AssetID] = e.Due
597				continue
598			}
599			if maintCreate[e.AssetID] == 0 {
600				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）出现在建立履历之前", e.AssetID, e.Seq)
601			}
602			if e.Due != derivedDue[e.AssetID] {
603				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）周期到期日 %s 与当前下一到期日 %s 不接续",
604					e.AssetID, e.Seq, e.Due, derivedDue[e.AssetID])
605			}
606			first, _ := parseDate(p.FirstDue)
607			done, _ := parseDate(e.Done)
608			next, ok := nextDueAfter(first, int64(p.IntervalDays), done)
609			if !ok {
610				return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）无法推出日期范围内的下一到期日",
611					e.AssetID, e.Seq)
612			}
613			derivedDue[e.AssetID] = formatDate(next)
614		}
615		for _, p := range d.Plans {
616			if maintCreate[p.AssetID] == 0 {
617				return fmt.Errorf("履历矛盾：资产 %s 的保养计划应有恰一条建立履历，实际没有", p.AssetID)
618			}
619			if derivedDue[p.AssetID] != p.NextDue {
620				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的下一到期日为 %s，与保存的 %s 不符",
621					p.AssetID, derivedDue[p.AssetID], p.NextDue)
622			}
623		}
624		return nil
625	}
