627	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
628	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
629	// 保持不变，不留下部分业务变化。
630	func (s *store) save() error {
631		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
632		for i, e := range s.data.Events {
633			s.data.EventsJSON[i] = e.toJSON()
634		}
635		if err := validateData(s.data); err != nil {
636			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
637		}
638		var buf bytes.Buffer
639		enc := json.NewEncoder(&buf)
640		enc.SetIndent("", "  ")
641		if err := enc.Encode(s.data); err != nil {
642			return fmt.Errorf("编码数据失败: %w", err)
643		}
644		if err := os.MkdirAll(s.dir, 0o755); err != nil {
645			return fmt.Errorf("创建数据目录失败: %w", err)
646		}
647		path := filepath.Join(s.dir, dataFileName)
648		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
649		if err != nil {
650			return fmt.Errorf("创建临时数据文件失败: %w", err)
651		}
652		tmpName := tmp.Name()
653		abort := func(err error) error {
654			_ = tmp.Close()
655			_ = os.Remove(tmpName)
656			return err
657		}
658		if _, err := tmp.Write(buf.Bytes()); err != nil {
659			abort(nil)
660			return fmt.Errorf("写入数据失败: %w", err)
661		}
662		if err := tmp.Sync(); err != nil {
663			abort(nil)
664			return fmt.Errorf("写入数据失败: %w", err)
665		}
666		if err := tmp.Close(); err != nil {
667			_ = os.Remove(tmpName)
668			return fmt.Errorf("写入数据失败: %w", err)
669		}
670		if err := os.Rename(tmpName, path); err != nil {
671			_ = os.Remove(tmpName)
672			return fmt.Errorf("保存数据失败: %w", err)
673		}
674		return nil
675	}
