677	func (s *store) findAsset(id string) *Asset {
678		for _, a := range s.data.Assets {
679			if a.ID == id {
680				return a
681			}
682		}
683		return nil
684	}
685	
686	func (s *store) findTicket(id string) *Ticket {
687		for _, t := range s.data.Tickets {
688			if t.ID == id {
689				return t
690			}
691		}
692		return nil
693	}
694	
695	func (s *store) findRequest(requestID string) *requestBinding {
696		for i := range s.data.Requests {
697			if s.data.Requests[i].RequestID == requestID {
698				return &s.data.Requests[i]
699			}
700		}
701		return nil
702	}
