713	func (s *store) eventsOf(assetID string) []Event {
714		out := make([]Event, 0)
715		for _, e := range s.data.Events {
716			if e.AssetID == assetID {
717				out = append(out, e)
718			}
719		}
720		sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
721		return out
722	}
723	
724	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
725	func (s *store) nextEventSeq() (int, error) {
726		maxSeq := 0
727		for _, e := range s.data.Events {
728			if e.Seq > maxSeq {
729				maxSeq = e.Seq
730			}
731		}
732		if maxSeq == math.MaxInt {
733			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
734		}
735		return maxSeq + 1, nil
736	}
737	
738	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
739	// 确保任何失败路径都不会在部分变更后才报错。from/to 仅派工履历使用。
740	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content, from, to string) {
741		s.data.Events = append(s.data.Events, Event{
742			Seq:      seq,
743			AssetID:  assetID,
744			TicketID: ticketID,
745			Kind:     kind,
746			Content:  content,
747			From:     from,
748			To:       to,
749			Time:     s.now(),
750		})
751	}
752	
753	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
754		if s.findAsset(id) != nil {
755			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
756		}
757		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
758		s.data.Assets = append(s.data.Assets, a)
759		return a, nil
760	}
761	
762	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
763	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
764	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
765		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
766		// 资产或描述不同 => 拒绝。
767		if r := s.findRequest(requestID); r != nil {
768			if r.AssetID != assetID || r.Description != description {
769				return nil, false, fmt.Errorf(
770					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
771					errConflict, requestID, r.AssetID)
772			}
773			t := s.findTicket(r.TicketID)
774			if t == nil {
775				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
776			}
777			return t, true, nil
778		}
779	
780		asset := s.findAsset(assetID)
781		if asset == nil {
782			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
783		}
784		if t := s.openTicketOf(assetID); t != nil {
785			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
786		}
787		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
788		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
789		seq := s.data.NextTicketSeq
790		if seq < 1 || seq == math.MaxInt {
791			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
792		}
793		eventSeq, err := s.nextEventSeq()
794		if err != nil {
795			return nil, false, err
796		}
797		t := &Ticket{
798			ID:          fmt.Sprintf("T%04d", seq),
799			AssetID:     assetID,
800			Description: description,
801			RequestID:   requestID,
802			Status:      ticketOpen,
803			CreatedAt:   s.now().Format(time.RFC3339),
804		}
805		s.data.NextTicketSeq = seq + 1
806		s.data.Tickets = append(s.data.Tickets, t)
807		s.data.Requests = append(s.data.Requests, requestBinding{
808			RequestID:   requestID,
809			AssetID:     assetID,
810			Description: description,
811			TicketID:    t.ID,
812		})
813		asset.Status = statusRepairing
814		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
815		return t, false, nil
816	}
817	
818	// closeTicket 关闭未关闭工单并把资产恢复为可用。
819	// 失败路径不修改任何业务数据。
820	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
821		t := s.findTicket(ticketID)
822		if t == nil {
823			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
824		}
825		if t.Status == ticketCancelled {
826			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
827		}
828		if t.Status != ticketOpen {
829			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
830		}
831		asset := s.findAsset(t.AssetID)
832		if asset == nil {
833			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
834		}
835		eventSeq, err := s.nextEventSeq()
836		if err != nil {
837			return nil, nil, err
838		}
839		t.Status = ticketClosed
840		t.Result = result
841		t.ClosedAt = s.now().Format(time.RFC3339)
842		asset.Status = statusAvailable
843		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
844		return t, asset, nil
845	}
846	
847	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
848	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
849	// 失败路径不修改任何业务数据。
850	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
851		t := s.findTicket(ticketID)
852		if t == nil {
853			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
854		}
855		if t.Status == ticketCancelled {
856			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
857		}
858		if t.Status == ticketClosed {
859			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
860		}
861		asset := s.findAsset(t.AssetID)
862		if asset == nil {
863			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
864		}
865		eventSeq, err := s.nextEventSeq()
866		if err != nil {
867			return nil, nil, err
868		}
869		t.Status = ticketCancelled
870		t.CancelReason = reason
871		t.CancelledAt = s.now().Format(time.RFC3339)
872		asset.Status = statusAvailable
873		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
874		return t, asset, nil
875	}
876	
877	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
878	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
879	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
880	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
881	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
882	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
883		t := s.findTicket(ticketID)
884		if t == nil {
885			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
886		}
887		if t.Status == ticketClosed {
888			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
889		}
890		if t.Status == ticketCancelled {
891			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
892		}
893		if assignee == "" {
894			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
895		}
896		if note == "" {
897			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
898		}
899		if t.Assignee == assignee {
900			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
901				errConflict, ticketID, assignee)
902		}
903		eventSeq, err := s.nextEventSeq()
904		if err != nil {
905			return nil, err
906		}
907		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
908		t.Assignee = assignee
909		t.AssignedAt = s.now().Format(time.RFC3339)
910		t.AssignNote = note
911		return t, nil
912	}
