1	package main
2	
3	import (
4		"errors"
5		"fmt"
6		"io"
7		"math"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12	)
13	
14	// 资产批量导入：把源数据目录中所选资产连同其全部工单、报修请求绑定、
15	// 报修/派工/关闭/取消履历与保养计划（含保养建立/完成履历）复制到目标数据目录。
16	//
17	// 关键规则：
18	//   - 导入是复制：源台账始终只读，不删除、不修改任何源记录；同一台账不能导入自身。
19	//   - 工单编号按源工单序号升序，从目标的下一工单序号重新分配，并同步替换履历与
20	//     请求绑定中的工单引用；目标原有记录不改编号、不改变业务含义。
21	//   - 履历按源履历序号排列，在目标已有最大履历序号之后依次分配新序号，保留原操作
22	//     顺序（不按时间重排）；履历时间保留原瞬间与小数秒精度。导入本身不追加报修
23	//     或其他业务事件。
24	//   - 保养计划随资产原样复制（内容、首次到期日、间隔与下一到期日不变），保养履历
25	//     随资产履历一并复制，完成链自然接续；目标已有计划不受影响。
26	//   - 资产编号在目标已存在，或所选工单的任一请求标识已在目标绑定时，整批拒绝：
27	//     不覆盖、不合并、不改请求标识。
28	//   - 操作前检查源、目标整库一致性，提交前由 save 再检查合并后的数据；整批变化
29	//     一次原子写入目标。任何失败都不改动两边原文件、不留下部分导入、不消耗目标编号。
30	
31	// stringListFlag 收集可重复的 --asset-id 参数。
32	type stringListFlag []string
33	
34	func (f *stringListFlag) String() string { return strings.Join(*f, ",") }
35	
36	func (f *stringListFlag) Set(v string) error {
37		*f = append(*f, v)
38		return nil
39	}
40	
41	// ticketRemap 记录一张工单的原编号与新编号。
42	type ticketRemap struct {
43		OldID string
44		NewID string
45	}
46	
47	// importOutcome 为一次成功导入的结果摘要，用于输出。
48	type importOutcome struct {
49		assetIDs []string
50		tickets  []ticketRemap
51		plans    int
52	}
53	
54	func cmdImport(args []string, w io.Writer) error {
55		var opts cmdOptions
56		var sourceDir string
57		var assetIDs stringListFlag
58		fs := newFlagSet("import", &opts)
59		fs.StringVar(&sourceDir, "source-dir", "", "源数据目录（必填，只读，不会被修改）")
60		fs.Var(&assetIDs, "asset-id", "要导入的资产编号（必填，可重复；重复编号按一项处理）")
61		if err := parseFlags(fs, args); err != nil {
62			return err
63		}
64		if err := requireFlag(fs, sourceDir, "source-dir"); err != nil {
65			return err
66		}
67		if len(assetIDs) == 0 {
68			return &usageError{msg: "命令 import 缺少必填参数 --asset-id（至少一项资产编号）"}
69		}
70		for _, id := range assetIDs {
71			if id == "" {
72				return &usageError{msg: "命令 import 的 --asset-id 不能为空"}
73			}
74		}
75	
76		outcome, err := importAssets(opts.dataDir, sourceDir, []string(assetIDs))
77		if err != nil {
78			return err
79		}
80		fmt.Fprintf(w, "已导入 %d 项资产（%s）。\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
81		if outcome.plans > 0 {
82			fmt.Fprintf(w, "同时导入 %d 项保养计划及其保养履历。\n", outcome.plans)
83		}
84		if len(outcome.tickets) == 0 {
85			fmt.Fprintln(w, "所选资产没有工单，未分配新工单编号。")
86			return nil
87		}
88		fmt.Fprintln(w, "工单编号映射（原编号 -> 新编号）:")
89		for _, m := range outcome.tickets {
90			fmt.Fprintf(w, "%s -> %s\n", m.OldID, m.NewID)
91		}
92		return nil
93	}
94	
95	// importAssets 把 sourceDir 中编号为 assetIDs 的资产导入 targetDir。
96	// 源目录只读；目标目录无台账时在成功导入时创建。任何一步失败都整批失败，
97	// 两边原文件字节保持不变。
98	func importAssets(targetDir, sourceDir string, assetIDs []string) (*importOutcome, error) {
99		srcAbs, err := filepath.Abs(sourceDir)
100		if err != nil {
101			return nil, fmt.Errorf("无法解析源数据目录: %w", err)
102		}
103		dstAbs, err := filepath.Abs(targetDir)
104		if err != nil {
105			return nil, fmt.Errorf("无法解析目标数据目录: %w", err)
106		}
107		if srcAbs == dstAbs {
108			return nil, errors.New("源数据目录与目标数据目录相同：同一台账不能导入自身")
109		}
110		// 路径不同也可能指向同一台账文件（符号链接等），按文件再判一次。
111		srcPath := filepath.Join(srcAbs, dataFileName)
112		dstPath := filepath.Join(dstAbs, dataFileName)
113		if fi1, err1 := os.Stat(srcPath); err1 == nil {
114			if fi2, err2 := os.Stat(dstPath); err2 == nil && os.SameFile(fi1, fi2) {
115				return nil, errors.New("源与目标指向同一台账文件：同一台账不能导入自身")
116			}
117		}
118	
119		// 源台账必须已存在并通过整库一致性检查；源始终只读，绝不写入。
120		src, err := openSourceStore(srcAbs)
121		if err != nil {
122			return nil, err
123		}
124		// 目标：无台账时视为空库（成功导入时创建）；已有台账同样先做整库一致性检查。
125		dst, err := openStore(dstAbs)
126		if err != nil {
127			return nil, err
128		}
129		outcome, err := dst.mergeImport(src, assetIDs)
130		if err != nil {
131			return nil, err
132		}
133		// save 先校验合并后的整库一致性，再一次性原子写入；失败时目标原文件不变。
134		if err := dst.save(); err != nil {
135			return nil, err
136		}
137		return outcome, nil
138	}
139	
140	// mergeImport 在内存中把源台账的所选资产合并进目标数据：先做全部冲突与容量
141	// 检查，再一次性应用，任何失败都不会留下部分变更。调用方负责随后的原子保存。
142	func (s *store) mergeImport(src *store, assetIDs []string) (*importOutcome, error) {
143		// 重复编号按一项处理，保持首次出现的顺序。
144		selected := map[string]bool{}
145		ids := make([]string, 0, len(assetIDs))
146		for _, id := range assetIDs {
147			if !selected[id] {
148				selected[id] = true
149				ids = append(ids, id)
150			}
151		}
152		// 所选资产必须存在于源，且编号在目标中不存在。
153		assets := make([]*Asset, 0, len(ids))
154		for _, id := range ids {
155			a := src.findAsset(id)
156			if a == nil {
157				return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
158			}
159			if s.findAsset(id) != nil {
160				return nil, fmt.Errorf("%w: 资产编号 %q 在目标台账中已存在，整批拒绝导入", errConflict, id)
161			}
162			assets = append(assets, a)
163		}
164		// 所选资产的全部工单，按源工单序号升序重新分配编号。
165		tickets := make([]*Ticket, 0)
166		for _, t := range src.data.Tickets {
167			if selected[t.AssetID] {
168				tickets = append(tickets, t)
169			}
170		}
171		sort.SliceStable(tickets, func(i, j int) bool {
172			ni, _ := parseTicketSeq(tickets[i].ID)
173			nj, _ := parseTicketSeq(tickets[j].ID)
174			return ni < nj
175		})
176		// 工单编号容量：与 report 同一约束，可分配的最大序号为 math.MaxInt-1。
177		if len(tickets) > math.MaxInt-s.data.NextTicketSeq {
178			return nil, fmt.Errorf(
179				"%w: 目标工单编号容量不足：下一序号 %d 无法容纳 %d 张导入工单，整批拒绝导入",
180				errConflict, s.data.NextTicketSeq, len(tickets))
181		}
182		// 所选工单的任一请求标识已在目标绑定时整批拒绝，不改请求标识。
183		srcReqByTicket := map[string]*requestBinding{}
184		for i := range src.data.Requests {
185			r := &src.data.Requests[i]
186			srcReqByTicket[r.TicketID] = r
187		}
188		for _, t := range tickets {
189			r := srcReqByTicket[t.ID]
190			if r == nil {
191				return nil, fmt.Errorf("数据内部错误：源工单 %s 缺少报修请求绑定", t.ID)
192			}
193			if s.findRequest(r.RequestID) != nil {
194				return nil, fmt.Errorf(
195					"%w: 所选工单的请求标识 %q 已在目标台账绑定，整批拒绝导入", errConflict, r.RequestID)
196			}
197		}
198		// 所选资产的全部履历，按源履历序号升序，在目标最大序号之后依次分配。
199		events := make([]Event, 0)
200		for _, e := range src.data.Events {
201			if selected[e.AssetID] {
202				events = append(events, e)
203			}
204		}
205		sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
206		maxSeq := 0
207		for _, e := range s.data.Events {
208			if e.Seq > maxSeq {
209				maxSeq = e.Seq
210			}
211		}
212		// 履历序号容量：与 nextEventSeq 同一约束，可分配的最大序号为 math.MaxInt。
213		if len(events) > math.MaxInt-maxSeq {
214			return nil, fmt.Errorf(
215				"%w: 目标履历序号容量不足：当前最大序号 %d 无法容纳 %d 条导入履历，整批拒绝导入",
216				errConflict, maxSeq, len(events))
217		}
218	
219		// 检查全部通过，一次性应用合并。资产编号、名称、位置、状态与工单的描述、
220		// 终态内容、负责人等业务信息原样保留；履历时间保留原瞬间与小数秒精度。
221		for _, a := range assets {
222			na := *a
223			s.data.Assets = append(s.data.Assets, &na)
224		}
225		// 所选资产的保养计划原样复制（内容、首次到期日、间隔与下一到期日不变）；
226		// 保养履历已随上方资产履历筛选一并复制，完成链自然接续。目标已有计划不变。
227		planCount := 0
228		for _, p := range src.data.Plans {
229			if selected[p.AssetID] {
230				np := *p
231				s.data.Plans = append(s.data.Plans, &np)
232				planCount++
233			}
234		}
235		outcome := &importOutcome{assetIDs: ids, plans: planCount}
236		remap := map[string]string{}
237		next := s.data.NextTicketSeq
238		for _, t := range tickets {
239			nt := *t
240			nt.ID = fmt.Sprintf("T%04d", next)
241			remap[t.ID] = nt.ID
242			s.data.Tickets = append(s.data.Tickets, &nt)
243			r := srcReqByTicket[t.ID]
244			s.data.Requests = append(s.data.Requests, requestBinding{
245				RequestID:   r.RequestID,
246				AssetID:     r.AssetID,
247				Description: r.Description,
248				TicketID:    nt.ID,
249			})
250			outcome.tickets = append(outcome.tickets, ticketRemap{OldID: t.ID, NewID: nt.ID})
251			next++
252		}
253		s.data.NextTicketSeq = next
254		seq := maxSeq
255		for _, e := range events {
256			seq++
257			ne := e
258			ne.Seq = seq
259			ne.TicketID = remap[e.TicketID]
260			s.data.Events = append(s.data.Events, ne)
261		}
262		return outcome, nil
263	}
