1	package main
2	
3	import (
4		"fmt"
5		"sort"
6	)
7	
8	// 周期保养计划与完成登记。
9	//
10	// 日期一律为 0001 至 9999 年的公历日历日（YYYY-MM-DD），按日历日运算：
11	// 不涉及时区与运行时刻，内部以“距 0001-01-01 的天数”做整数运算，避免
12	// time.Time 的时区、跨度（time.Duration 约 292 年上限）与年份范围问题。
13	//
14	// 每个计划恰有一条建立履历（含初始计划：内容、首次到期日、间隔天数），
15	// 每次完成登记追加一条完成履历（含周期到期日、实际完成日、结果）。计划的
16	// 下一到期日由履历链推出并保存在计划中，加载与保存时核对二者一致。
17	// 保养不创建或终结工单、不消耗工单编号，不改变资产状态、请求绑定或停机统计。
18	
19	// Plan 为资产的周期保养计划；每项资产最多一个，不可覆盖。
20	// NextDue 为由履历链推出的下一到期日，随每次完成登记推进。
21	type Plan struct {
22		AssetID      string `json:"asset_id"`
23		Content      string `json:"content"`
24		FirstDue     string `json:"first_due"`
25		IntervalDays int    `json:"interval_days"`
26		NextDue      string `json:"next_due"`
27	}
28	
29	// maxDayNum 为 9999-12-31 的日序号（0001-01-01 为 0）。
30	const maxDayNum = 3652058
31	
32	// daysFromCivil 返回公历日期距 0001-01-01 的天数（该日为 0）。
33	// 输入须为 0001 至 9999 年间的有效日期（由 parseDate 保证）。
34	func daysFromCivil(y, m, d int) int64 {
35		yy := int64(y)
36		if m <= 2 {
37			yy--
38		}
39		era := yy / 400
40		yoe := yy - era*400
41		mp := int64((m + 9) % 12)
42		doy := (153*mp+2)/5 + int64(d) - 1
43		doe := yoe*365 + yoe/4 - yoe/100 + doy
44		return era*146097 + doe - 306
45	}
46	
47	// civilFromDays 为 daysFromCivil 的逆运算。
48	func civilFromDays(n int64) (int, int, int) {
49		z := n + 306
50		era := z / 146097
51		doe := z - era*146097
52		yoe := (doe - doe/1460 + doe/36524 - doe/146096) / 365
53		y := yoe + era*400
54		doy := doe - (365*yoe + yoe/4 - yoe/100)
55		mp := (5*doy + 2) / 153
56		d := doy - (153*mp+2)/5 + 1
57		if mp < 10 {
58			return int(y), int(mp + 3), int(d)
59		}
60		return int(y + 1), int(mp - 9), int(d)
61	}
62	
63	func isLeapYear(y int) bool {
64		return y%4 == 0 && (y%100 != 0 || y%400 == 0)
65	}
66	
67	func daysInMonth(y, m int) int {
68		switch m {
69		case 1, 3, 5, 7, 8, 10, 12:
70			return 31
71		case 4, 6, 9, 11:
72			return 30
73		}
74		if isLeapYear(y) {
75			return 29
76		}
77		return 28
78	}
79	
80	// atoiN 解析定长十进制数字串；含非数字字符时 ok=false。
81	func atoiN(s string) (int, bool) {
82		n := 0
83		for i := 0; i < len(s); i++ {
84			if s[i] < '0' || s[i] > '9' {
85				return 0, false
86			}
87			n = n*10 + int(s[i]-'0')
88		}
89		return n, true
90	}
91	
92	// parseDate 解析 YYYY-MM-DD 形式的公历日期（0001 至 9999 年，须为零填充的
93	// 完整形式），返回日序号。闰日等按公历规则校验。
94	func parseDate(s string) (int64, error) {
95		if len(s) != 10 || s[4] != '-' || s[7] != '-' {
96			return 0, fmt.Errorf("不是 YYYY-MM-DD 形式: %q", s)
97		}
98		y, ok1 := atoiN(s[0:4])
99		m, ok2 := atoiN(s[5:7])
100		d, ok3 := atoiN(s[8:10])
101		if !ok1 || !ok2 || !ok3 {
102			return 0, fmt.Errorf("不是 YYYY-MM-DD 形式: %q", s)
103		}
104		if y < 1 || m < 1 || m > 12 || d < 1 || d > daysInMonth(y, m) {
105			return 0, fmt.Errorf("不是 0001 至 9999 年间的有效公历日期: %q", s)
106		}
107		return daysFromCivil(y, m, d), nil
108	}
109	
110	// formatDate 把日序号格式化为 YYYY-MM-DD。
111	func formatDate(n int64) string {
112		y, m, d := civilFromDays(n)
113		return fmt.Sprintf("%04d-%02d-%02d", y, m, d)
114	}
115	
116	// nextDueAfter 返回首次到期日加整数倍间隔所得日期中，严格晚于 after 的最早
117	// 日期。结果超出 9999-12-31 时 ok=false。间隔必须为正整数。
118	func nextDueAfter(first, interval, after int64) (int64, bool) {
119		var k int64
120		if after >= first {
121			k = (after-first)/interval + 1
122		}
123		// k ≥ 1 且间隔本身已超出剩余日期范围时，结果必然越界；先判断避免溢出。
124		if k > 0 && interval > maxDayNum-first {
125			return 0, false
126		}
127		n := first + k*interval
128		if n > maxDayNum {
129			return 0, false
130		}
131		return n, true
132	}
133	
134	// findPlan 返回资产的保养计划，无计划时返回 nil。
135	func (s *store) findPlan(assetID string) *Plan {
136		for _, p := range s.data.Plans {
137			if p.AssetID == assetID {
138				return p
139			}
140		}
141		return nil
142	}
143	
144	// appendMaintEvent 以给定序号追加保养履历（建立或完成）。保养履历不属于任何
145	// 工单，from/to 恒为空；due/done/interval 按履历类型使用。
146	func (s *store) appendMaintEvent(seq int, assetID, kind, content, due, done string, interval int) {
147		s.data.Events = append(s.data.Events, Event{
148			Seq:      seq,
149			AssetID:  assetID,
150			Kind:     kind,
151			Content:  content,
152			Due:      due,
153			Done:     done,
154			Interval: interval,
155			Time:     s.now(),
156		})
157	}
158	
159	// createPlan 为资产建立唯一的周期保养计划：每项资产最多一个，已有计划时拒绝，
160	// 不覆盖。成功时追加一条含初始计划的建立履历，下一到期日即首次到期日。
161	// 失败路径不修改任何业务数据。
162	func (s *store) createPlan(assetID, content, firstDue string, intervalDays int) (*Plan, error) {
163		if s.findAsset(assetID) == nil {
164			return nil, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
165		}
166		if s.findPlan(assetID) != nil {
167			return nil, fmt.Errorf("%w: 资产 %s 已有保养计划，不能重复建立或覆盖", errConflict, assetID)
168		}
169		if content == "" {
170			return nil, fmt.Errorf("%w: 保养内容不能为空", errConflict)
171		}
172		if intervalDays < 1 {
173			return nil, fmt.Errorf("%w: 保养间隔天数须为正整数", errConflict)
174		}
175		if _, err := parseDate(firstDue); err != nil {
176			return nil, fmt.Errorf("%w: 首次到期日无效：%s", errConflict, err)
177		}
178		eventSeq, err := s.nextEventSeq()
179		if err != nil {
180			return nil, err
181		}
182		p := &Plan{
183			AssetID:      assetID,
184			Content:      content,
185			FirstDue:     firstDue,
186			IntervalDays: intervalDays,
187			NextDue:      firstDue,
188		}
189		s.data.Plans = append(s.data.Plans, p)
190		s.appendMaintEvent(eventSeq, assetID, eventPlanCreate, content, firstDue, "", intervalDays)
191		return p, nil
192	}
193	
194	// completePlan 登记当前周期的保养完成：所填到期日必须等于当前下一到期日
195	// （旧周期不能重复登记，也不能登记尚未到期的新周期），实际完成日不得早于
196	// 周期到期日。成功时追加一条完成履历，并把下一到期日推进到首次到期日加整数倍
197	// 间隔所得日期中严格晚于完成日的最早日期；延期跨过的周期不生成完成记录。
198	// 若下一到期日超出 9999-12-31，整次拒绝。失败路径不修改任何业务数据。
199	func (s *store) completePlan(assetID, due, done, result string) (*Plan, string, error) {
200		if s.findAsset(assetID) == nil {
201			return nil, "", fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
202		}
203		p := s.findPlan(assetID)
204		if p == nil {
205			return nil, "", fmt.Errorf("%w: 资产 %s 没有保养计划", errNotFound, assetID)
206		}
207		if result == "" {
208			return nil, "", fmt.Errorf("%w: 保养结果不能为空", errConflict)
209		}
210		dueN, err := parseDate(due)
211		if err != nil {
212			return nil, "", fmt.Errorf("%w: 周期到期日无效：%s", errConflict, err)
213		}
214		doneN, err := parseDate(done)
215		if err != nil {
216			return nil, "", fmt.Errorf("%w: 实际完成日无效：%s", errConflict, err)
217		}
218		if due != p.NextDue {
219			return nil, "", fmt.Errorf(
220				"%w: 周期到期日 %s 与资产 %s 当前下一到期日 %s 不符（旧周期不能重复登记，也不能登记新周期）",
221				errConflict, due, assetID, p.NextDue)
222		}
223		if doneN < dueN {
224			return nil, "", fmt.Errorf("%w: 实际完成日 %s 早于周期到期日 %s", errConflict, done, due)
225		}
226		first, _ := parseDate(p.FirstDue)
227		next, ok := nextDueAfter(first, int64(p.IntervalDays), doneN)
228		if !ok {
229			return nil, "", fmt.Errorf(
230				"%w: 按完成日 %s 推算的下一到期日超出 9999-12-31，无法登记本次完成", errConflict, done)
231		}
232		eventSeq, err := s.nextEventSeq()
233		if err != nil {
234			return nil, "", err
235		}
236		p.NextDue = formatDate(next)
237		s.appendMaintEvent(eventSeq, assetID, eventPlanDone, result, due, done, 0)
238		return p, p.NextDue, nil
239	}
240	
241	// duePlanRow 为到期查询的一行结果。
242	type duePlanRow struct {
243		AssetID string
244		Name    string
245		Content string
246		Due     string
247	}
248	
249	// duePlans 列出下一到期日不晚于 date 的保养计划，按到期日再按资产编号排序。
250	// 只读：不写文件、不初始化目录、不推进计划。date 须为有效日期（调用方校验）。
251	func (s *store) duePlans(date string) []duePlanRow {
252		rows := make([]duePlanRow, 0)
253		for _, p := range s.data.Plans {
254			// YYYY-MM-DD 零填充形式的字典序即时间顺序。
255			if p.NextDue > date {
256				continue
257			}
258			a := s.findAsset(p.AssetID)
259			if a == nil {
260				continue // 整库一致性检查已保证归属；防御性跳过
261			}
262			rows = append(rows, duePlanRow{AssetID: p.AssetID, Name: a.Name, Content: p.Content, Due: p.NextDue})
263		}
264		sort.Slice(rows, func(i, j int) bool {
265			if rows[i].Due != rows[j].Due {
266				return rows[i].Due < rows[j].Due
267			}
268			return rows[i].AssetID < rows[j].AssetID
269		})
270		return rows
271	}
