242		// 源：序号有间隔、事件数组乱序、派工时间早于报修时间（时间不递增），
243		// 履历时间含小数秒。
244		srcLedger := `{
245	  "version": 1,
246	  "assets": [{"id":"EQ-1","name":"打印机","location":"一楼","status":"可用"}],
247	  "tickets": [{"id":"T0003","asset_id":"EQ-1","description":"卡纸","request_id":"req-1","status":"已关闭",
248	    "result":"已修复","created_at":"2026-10-01T08:00:00.123456789Z","closed_at":"2026-10-01T09:30:00.000000001Z",
249	    "assignee":"张三","assigned_at":"2026-10-01T07:00:00.25Z","assign_note":"上门"}],
250	  "events": [
251	    {"seq":7,"asset_id":"EQ-1","ticket_id":"T0003","kind":"关闭","content":"已修复","time":"2026-10-01T09:30:00.000000001Z"},
252	    {"seq":2,"asset_id":"EQ-1","ticket_id":"T0003","kind":"报修","content":"卡纸","time":"2026-10-01T08:00:00.123456789Z"},
253	    {"seq":5,"asset_id":"EQ-1","ticket_id":"T0003","kind":"派工","content":"上门","from":"","to":"张三","time":"2026-10-01T07:00:00.25Z"}
254	  ],
255	  "requests": [{"request_id":"req-1","asset_id":"EQ-1","description":"卡纸","ticket_id":"T0003"}],
256	  "next_ticket_seq": 9
257	}`
258		if err := os.WriteFile(filepath.Join(srcDir, dataFileName), []byte(srcLedger), 0o644); err != nil {
259			t.Fatal(err)
260		}
261		// 目标：原有履历带小数秒 .75，最大履历序号 4。
262		dstLedger := `{
263	  "version": 1,
264	  "assets": [{"id":"EQ-9","name":"空调","location":"二楼","status":"维修中"}],
265	  "tickets": [{"id":"T0001","asset_id":"EQ-9","description":"不制冷","request_id":"req-9","status":"未关闭","created_at":"2026-09-01T10:00:00Z"}],
266	  "events": [{"seq":4,"asset_id":"EQ-9","ticket_id":"T0001","kind":"报修","content":"不制冷","time":"2026-09-01T10:00:00.75Z"}],
267	  "requests": [{"request_id":"req-9","asset_id":"EQ-9","description":"不制冷","ticket_id":"T0001"}],
268	  "next_ticket_seq": 2
269	}`
270		if err := os.WriteFile(filepath.Join(dstDir, dataFileName), []byte(dstLedger), 0o644); err != nil {
271			t.Fatal(err)
272		}
273	
274		outcome, err := importAssets(dstDir, srcDir, []string{"EQ-1"})
275		if err != nil {
276			t.Fatalf("导入旧库失败: %v", err)
277		}
278		if len(outcome.tickets) != 1 || outcome.tickets[0] != (ticketRemap{"T0003", "T0002"}) {
279			t.Fatalf("映射应为 T0003 -> T0002，得到 %+v", outcome.tickets)
280		}
281	
282		// 目标文件字节层面保留小数秒：导入的与目标原有的都不被截断。
283		raw := readFileBytes(t, dstDir)
284		for _, frag := range []string{"123456789", "000000001", "07:00:00.25", "10:00:00.75"} {
285			if !strings.Contains(string(raw), frag) {
286				t.Fatalf("保存后的目标文件应保留小数秒片段 %q", frag)
287			}
288		}
289	
290		s, err := openStore(dstDir)
291		if err != nil {
292			t.Fatalf("重载: %v", err)
293		}
294		// 履历按源序号顺序（报修、派工、关闭）排在目标最大序号 4 之后，不按时间重排。
295		ev := s.eventsOf("EQ-1")
296		if len(ev) != 3 {
297			t.Fatalf("履历数 = %d, 想得到 3", len(ev))
298		}
299		want := []struct {
300			seq  int
301			kind string
302			ts   string
303		}{
304			{5, eventReport, "2026-10-01T08:00:00.123456789Z"},
305			{6, eventAssign, "2026-10-01T07:00:00.25Z"},
306			{7, eventClose, "2026-10-01T09:30:00.000000001Z"},
307		}
308		for i, w := range want {
309			wantTime, err := time.Parse(time.RFC3339Nano, w.ts)
310			if err != nil {
311				t.Fatal(err)
312			}
313			if ev[i].Seq != w.seq || ev[i].Kind != w.kind || !ev[i].Time.Equal(wantTime) {
314				t.Fatalf("履历[%d] = seq %d %s %s, 想得到 seq %d %s %s",
315					i, ev[i].Seq, ev[i].Kind, ev[i].Time, w.seq, w.kind, w.ts)
316			}
317			if ev[i].TicketID != "T0002" {
318				t.Fatalf("履历[%d 工单引用应为 T0002，得到 %s", i, ev[i].TicketID)
319			}
320		}
321		// 目标原有履历时间精度不损失。
322		evX := s.eventsOf("EQ-9")
323		wantX, _ := time.Parse(time.RFC3339Nano, "2026-09-01T10:00:00.75Z")
324		if len(evX) != 1 || !evX[0].Time.Equal(wantX) {
325			t.Fatalf("目标原有履历时间应保持 .75，得到 %+v", evX)
326		}
327		// 工单记录上的时间字符串原样保留。
328		if tk := s.findTicket("T0002"); tk.CreatedAt != "2026-10-01T08:00:00.123456789Z" ||
329			tk.ClosedAt != "2026-10-01T09:30:00.000000001Z" {
330			t.Fatalf("工单时间字段应原样保留，得到 %+v", tk)
331		}
332		// 导入资产的停机统计规则不变：08:00:00.123456789 -> 09:30:00.000000001
333		// 精确时长 5399.876543212 秒，向下取整 5399 秒。
334		start, _ := time.Parse(time.RFC3339, "2026-10-01T00:00:00Z")
335		end, _ := time.Parse(time.RFC3339, "2026-10-02T00:00:00Z")
336		res, err := s.downtimeForAssets([]string{"EQ-1"}, start, end)
337		if err != nil {
338			t.Fatalf("停机统计: %v", err)
339		}
340		if res[0].Seconds != 5399 {
341			t.Fatalf("停机秒数 = %d, 想得到 5399", res[0].Seconds)
342		}
343	}
