406	// 容量：目标工单编号或履历序号容量不足时整批失败，不消耗编号，文件不变。
407	func TestImportCapacityFailures(t *testing.T) {
408		srcDir := filepath.Join(t.TempDir(), "src")
409		src := newStoreAt(t, srcDir)
410		if _, err := src.registerAsset("EQ-S", "打印机", "一楼"); err != nil {
411			t.Fatal(err)
412		}
413		if _, _, err := src.report("EQ-S", "卡纸", "req-s1"); err != nil {
414			t.Fatal(err)
415		}
416		mustSave(t, src)
417	
418		writeDst := func(t *testing.T, nextTicketSeq, maxEventSeq int) (string, []byte) {
419			t.Helper()
420			dir := t.TempDir()
421			ledger := fmt.Sprintf(`{
422	  "version": 1,
423	  "assets": [{"id":"EQ-T","name":"空调","location":"二楼","status":"维修中"}],
424	  "tickets": [{"id":"T0001","asset_id":"EQ-T","description":"不制冷","request_id":"req-t1","status":"未关闭","created_at":"2026-09-01T10:00:00Z"}],
425	  "events": [{"seq":%[2]d,"asset_id":"EQ-T","ticket_id":"T0001","kind":"报修","content":"不制冷","time":"2026-09-01T10:00:00Z"}],
426	  "requests": [{"request_id":"req-t1","asset_id":"EQ-T","description":"不制冷","ticket_id":"T0001"}],
427	  "next_ticket_seq": %[1]d
428	}`, nextTicketSeq, maxEventSeq)
429			raw := []byte(ledger)
430			if err := os.WriteFile(filepath.Join(dir, dataFileName), raw, 0o644); err != nil {
431				t.Fatal(err)
432			}
433			return dir, raw
434		}
435	
436		// 工单编号容量不足：下一序号已为 math.MaxInt，无法再分配。
437		dstDir, dstBefore := writeDst(t, math.MaxInt, 1)
438		srcBefore := readFileBytes(t, srcDir)
439		if _, err := importAssets(dstDir, srcDir, []string{"EQ-S"}); !errors.Is(err, errConflict) {
440			t.Fatalf("工单编号容量不足应冲突拒绝，得到 %v", err)
441		}
442		if string(readFileBytes(t, dstDir)) != string(dstBefore) ||
443			string(readFileBytes(t, srcDir)) != string(srcBefore) {
444			t.Fatal("容量不足拒绝不应改动任何文件")
445		}
446	
447		// 履历序号容量不足：目标最大履历序号已为 math.MaxInt。
448		dstDir2, dstBefore2 := writeDst(t, 2, math.MaxInt)
449		if _, err := importAssets(dstDir2, srcDir, []string{"EQ-S"}); !errors.Is(err, errConflict) {
450			t.Fatalf("履历序号容量不足应冲突拒绝，得到 %v", err)
451		}
452		if string(readFileBytes(t, dstDir2)) != string(dstBefore2) {
