457	// 写入失败：目标目录不可写时整批失败，两边原文件字节不变，
458	// 重载后无部分资产、履历或请求绑定，目标编号未被消耗。
459	func TestImportWriteFailureLeavesFilesUntouched(t *testing.T) {
460		srcDir := filepath.Join(t.TempDir(), "src")
461		src := newStoreAt(t, srcDir)
462		if _, err := src.registerAsset("EQ-S", "打印机", "一楼"); err != nil {
463			t.Fatal(err)
464		}
465		if _, _, err := src.report("EQ-S", "卡纸", "req-s1"); err != nil {
466			t.Fatal(err)
467		}
468		mustSave(t, src)
469	
470		dstDir := filepath.Join(t.TempDir(), "dst")
471		dst := newStoreAt(t, dstDir)
472		if _, err := dst.registerAsset("EQ-X", "叉车", "仓库"); err != nil {
473			t.Fatal(err)
474		}
475		mustSave(t, dst)
476		srcBefore, dstBefore := readFileBytes(t, srcDir), readFileBytes(t, dstDir)
477	
478		if err := os.Chmod(dstDir, 0o555); err != nil {
479			t.Fatal(err)
480		}
481		_, err := importAssets(dstDir, srcDir, []string{"EQ-S"})
482		if cerr := os.Chmod(dstDir, 0o755); cerr != nil {
483			t.Fatal(cerr)
484		}
485		if err == nil {
486			t.Skip("当前环境允许只读目录写入，跳过写入失败分支")
487		}
488		if string(readFileBytes(t, srcDir)) != string(srcBefore) ||
489			string(readFileBytes(t, dstDir)) != string(dstBefore) {
490			t.Fatal("写入失败不应改动任何文件")
491		}
492		s, err := openStore(dstDir)
493		if err != nil {
494			t.Fatalf("写入失败后目标台账应可正常重载: %v", err)
495		}
496		if s.findAsset("EQ-S") != nil || len(s.data.Tickets) != 0 || len(s.data.Events) != 0 ||
497			len(s.data.Requests) != 0 || s.data.NextTicketSeq != 1 {
498			t.Fatal("写入失败不应留下部分导入，也不应消耗目标编号")
499		}
500		// 恢复可写后同一批导入可以重新提交成功。
501		if _, err := importAssets(dstDir, srcDir, []string{"EQ-S"}); err != nil {
502			t.Fatalf("恢复可写后导入应成功: %v", err)
503		}
504		s2, err := openStore(dstDir)
505		if err != nil || s2.findAsset("EQ-S") == nil {
506			t.Fatalf("重新提交后应能重载到导入资产: %v", err)
507		}
508	}
509	
510	// 源台账不存在时不能当空库初始化；目标无台账时成功导入会创建；
511	// 同一台账不能导入自身。
512	func TestImportSourceAndSelfChecks(t *testing.T) {
513		srcDir := filepath.Join(t.TempDir(), "src")
514		src := newStoreAt(t, srcDir)
515		if _, err := src.registerAsset("EQ-S", "打印机", "一楼"); err != nil {
516			t.Fatal(err)
517		}
518		mustSave(t, src)
519	
520		// 源不存在：失败，且目标不会被创建。
521		missing := filepath.Join(t.TempDir(), "no-such-dir")
522		dstDir := filepath.Join(t.TempDir(), "dst")
523		if _, err := importAssets(dstDir, missing, []string{"EQ-S"}); err == nil {
524			t.Fatal("源台账不存在应失败")
525		}
526		if _, err := os.Stat(filepath.Join(dstDir, dataFileName)); !errors.Is(err, os.ErrNotExist) {
527			t.Fatal("源不存在时不应创建目标台账")
528		}
529	
530		// 同一台账不能导入自身（同一路径）。
531		if _, err := importAssets(srcDir, srcDir, []string{"EQ-S"}); err == nil {
532			t.Fatal("同一台账导入自身应失败")
533		}
534	
535		// 目标无台账：成功导入时创建。
536		outcome, err := importAssets(dstDir, srcDir, []string{"EQ-S"})
537		if err != nil {
538			t.Fatalf("目标无台账时应能创建并导入: %v", err)
539		}
540		if len(outcome.tickets) != 0 {
541			t.Fatalf("无工单资产不应产生编号映射，得到 %+v", outcome.tickets)
542		}
543		s, err := openStore(dstDir)
544		if err != nil {
545			t.Fatalf("导入后目标台账应可打开: %v", err)
546		}
547		if a := s.findAsset("EQ-S"); a == nil || a.Status != statusAvailable {
548			t.Fatalf("导入资产应存在且为可用，得到 %+v", a)
549		}
550	}
551	
552	// 命令行入口：参数错误退出 2，业务失败退出 1，成功输出资产数量与编号映射。
553	func TestImportCommandLine(t *testing.T) {
554		srcDir := filepath.Join(t.TempDir(), "src")
555		src := newStoreAt(t, srcDir)
556		if _, err := src.registerAsset("EQ-S", "打印机", "一楼"); err != nil {
557			t.Fatal(err)
558		}
559		if _, _, err := src.report("EQ-S", "卡纸", "req-s1"); err != nil {
560			t.Fatal(err)
561		}
562		mustSave(t, src)
563		dstDir := filepath.Join(t.TempDir(), "dst")
564	
565		var out, errOut bytes.Buffer
566		if code := run([]string{"import", "--source-dir", srcDir, "--data-dir", dstDir}, &out, &errOut); code != 2 {
567			t.Fatalf("缺少 --asset-id 应退出 2，得到 %d（%s）", code, errOut.String())
568		}
569		out.Reset()
570		if code := run([]string{"import", "--source-dir", srcDir, "--asset-id", "EQ-S", "--data-dir", dstDir}, &out, &errOut); code != 0 {
571			t.Fatalf("导入应成功，得到 %d（%s）", code, errOut.String())
572		}
573		if !strings.Contains(out.String(), "已导入 1 项资产") ||
574			!strings.Contains(out.String(), "T0001 -> T0001") {
575			t.Fatalf("输出应包含资产数量与编号映射，得到:\n%s", out.String())
576		}
577		// 再次导入同一批资产：编号冲突，退出 1。
578		out.Reset()
579		errOut.Reset()
580		if code := run([]string{"import", "--source-dir", srcDir, "--asset-id", "EQ-S", "--data-dir", dstDir}, &out, &errOut); code != 1 {
581			t.Fatalf("再次导入应退出 1，得到 %d（%s）", code, errOut.String())
582		}
583	}
