	return eventJSON{
		Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
		Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
		Due: e.Due, Done: e.Done, Interval: e.Interval,
		// RFC3339Nano 保留小数秒精度；整秒时输出与 RFC3339 完全一致，
