		// 在重新保存（含导入合并后的提交）时也不会被截断。
		Time: e.Time.Format(time.RFC3339Nano),
	}
}

func (e eventJSON) toEvent() (Event, error) {
	t, err := time.Parse(time.RFC3339, e.Time)
	if err != nil {
