// parseIssueSeq 解析 P 加补零正整数序号形式的领用编号，返回序号。
// 编号必须与 fmt.Sprintf("P%04d", n)（n ≥ 1）完全一致，否则视为非法。
func parseIssueSeq(id string) (int, bool) {
	if !strings.HasPrefix(id, "P") {
		return 0, false
	}
	n, err := strconv.Atoi(id[1:])
	if err != nil || n < 1 {
		return 0, false
	}
	if fmt.Sprintf("P%04d", n) != id {
		return 0, false
	}
	return n, true
}

